import unittest

class Test(unittest.TestCase):
    def test_full_cycle(self):
        t = TrafficLight()
        seq = [t.tick() for _ in range(6)]
        self.assertEqual(seq, ['red','red','red','green','green','yellow'])
    def test_wraps_around(self):
        t = TrafficLight()
        for _ in range(6):
            t.tick()
        self.assertEqual(t.tick(), 'red')

if __name__ == '__main__':
    unittest.main()
